  ('64b8894167c3', 'bluff', 'knowledge', '冷门成语', 1, '「文不加点」是什么意思？', '写文章一气呵成，不用修改', '「点」是涂改的意思，不是标点。', true),
  ('4f1e4dfb1d0c', 'bluff', 'knowledge', '冷门成语', 1, '「曾参杀人」是什么意思？', '谣言说的人多了，连最亲的人都会相信', '有个同名的人杀了人，有人连着三次跟曾参的母亲说「曾参杀人了」，她最后吓得翻墙逃走。', true),
  ('c8f1f6e2323d', 'bluff', 'knowledge', '冷门成语', 1, '「吴牛喘月」是什么意思？', '因为吃过亏，见到相似的东西就害怕', '吴地天热，水牛怕晒，看到月亮以为是太阳，就喘起气来。', true),
  ('816841b58b24', 'bluff', 'knowledge', '冷门成语', 1, '「蜀犬吠日」是什么意思？', '少见多怪', '四川多雾，很少出太阳，狗一见到太阳就叫。', true),
  ('ee9f60881c2c', 'bluff', 'knowledge', '冷门成语', 1, '「弹冠相庆」是什么意思？', '一个人当了官，他的同伙也互相庆祝、准备跟着做官（贬义）', '「弹冠」是掸掉帽子上的灰，准备戴上去做官。', true),
  ('b2b5d67cfa89', 'bluff', 'knowledge', '冷门成语', 1, '「牛骥同皂」是什么意思？', '好的坏的混在一起，不加区分', '「骥」是千里马，「皂」是喂牲口的槽：千里马和牛在一个槽里吃饭。', true),
  ('526044865062', 'bluff', 'knowledge', '冷门成语', 1, '「尾生抱柱」是什么意思？', '死守约定、不知变通', '尾生和女子约在桥下见面，女子没来，河水涨了他也不走，抱着桥柱被淹死。', true),
  ('471ee1782cae', 'bluff', 'knowledge', '冷门成语', 1, '「周郎顾曲」是什么意思？', '形容精通音乐的人', '周瑜懂音乐，酒喝多了也能听出别人弹错，听到错处就会回头看。', true),
  ('83a7f2561dd9', 'bluff', 'knowledge', '冷门成语', 1, '「青蝇吊客」是什么意思？', '生前没有知己', '三国虞翻说自己死后只有苍蝇来吊唁。', true),
  ('4b7dba242431', 'bluff', 'knowledge', '冷门成语', 1, '「差强人意」是什么意思？', '大体上还能让人满意', '「差」是稍微、勉强的意思，不是「差劲」。', true),
  ('c33d45927753', 'bluff', 'knowledge', '冷门词汇', 1, '「孑孓」是什么？｜昆虫', '蚊子的幼虫', '生活在水里，一扭一扭地游，民间也叫跟头虫。', true),
  ('b5246c3634a7', 'bluff', 'knowledge', '冷门词汇', 1, '「赑屃」是什么？｜古建筑', '传说中龙的儿子之一，长得像乌龟，喜欢驮重东西', '古代石碑底下驮着碑的「大乌龟」就是它。', true),
  ('61ae3c486ac5', 'bluff', 'knowledge', '冷门词汇', 1, '「狻猊」是什么？｜神话', '传说中龙的儿子之一，长得像狮子，喜欢烟火', '常被雕在香炉上。', true),
  ('88e6964e6dd0', 'bluff', 'knowledge', '冷门词汇', 1, '「蟏蛸」是什么？｜昆虫', '一种腿很长的小蜘蛛', '（卡片上写的领域是假的）蜘蛛不是昆虫。民间叫它「喜蛛」，《诗经》里有「蟏蛸在户」。', true),
  ('dc65b8e1b29b', 'bluff', 'knowledge', '冷门词汇', 1, '「醍醐」是什么？｜饮食', '从牛奶里提炼出来的精华', '「醍醐灌顶」原意就是把这种精华浇到头上。', true),
  ('63dc633af601', 'bluff', 'knowledge', '冷门词汇', 1, '「爝火」是什么？｜古代用品', '小火把，很微弱的火光', null, true),
  ('e02c1a454a88', 'bluff', 'knowledge', '冷门词汇', 1, '「蚍蜉」是什么？｜昆虫', '大蚂蚁', '「蚍蜉撼树」就是大蚂蚁想摇动大树。', true),
  ('2c69a4500225', 'bluff', 'knowledge', '冷门词汇', 1, '「鸱吻」是什么？｜古建筑', '古建筑屋脊两头的龙头形装饰', '传说是龙的儿子，能喷水，放在屋顶防火。', true),
  ('35b03808d5ff', 'bluff', 'knowledge', '冷门词汇', 1, '「睚眦」是什么？｜兵器', '传说中龙的儿子之一，脾气大、爱打杀', '（卡片上写的领域是假的）它常被刻在刀柄、剑鞘上，本身是神兽。', true),
  ('9408ece37b39', 'bluff', 'knowledge', '冷门词汇', 1, '「藻井」是什么？｜水利', '古建筑天花板中间往上凹进去的装饰', '（卡片上写的领域是假的）跟井没关系，宫殿和寺庙里抬头能看到，画有水草图案，寓意防火。', true),
