  ('f52a1b9f201d', 'bluff', 'knowledge', '冷门词汇', 1, '「蠹鱼」是什么？｜昆虫', '一种银色的小虫，爱啃书和衣服', '也叫衣鱼，「书蠹」说的就是它。', true),
  ('219e59365d4c', 'bluff', 'knowledge', '冷门词汇', 1, '「翡翠」是什么？｜珠宝', '最早指一种鸟：红色的雄鸟叫翡，绿色的雌鸟叫翠', '（卡片上写的领域是假的）后来才用来叫颜色像它羽毛的玉石。', true),
