  ('6a69fbe02714', 'bluff', 'knowledge', '冷门成语', 1, '「金龟换酒」是什么意思？', '形容豪爽好客、不拘小节', '贺知章初见李白，解下身上佩戴的金龟换酒请他喝。', true),
  ('f6b9a649681a', 'bluff', 'knowledge', '冷门成语', 1, '「曲突徙薪」是什么意思？', '提前采取措施，防患于未然', '有人劝主人把直烟囱改成弯的、把柴搬远，主人不听，后来果然失火。', true),
  ('08d179d86b8c', 'bluff', 'knowledge', '冷门成语', 1, '「焚琴煮鹤」是什么意思？', '糟蹋美好的东西，大煞风景', '把琴当柴烧，把仙鹤煮了吃。', true),
  ('5648f347a002', 'bluff', 'knowledge', '冷门成语', 1, '「胶柱鼓瑟」是什么意思？', '死板，不知道变通', '把瑟上调音的柱子用胶粘死再弹，就没法调音了。', true),
